package com.wingedsheep.engine.mechanics.layers

import com.wingedsheep.engine.state.GameState
import com.wingedsheep.engine.state.components.battlefield.TimestampComponent
import com.wingedsheep.sdk.model.EntityId

/**
 * Gives a permanent a new layer-system timestamp ([TimestampComponent]) — the value every
 * continuous effect generated by its static abilities sorts by (CR 613.7a).
 *
 * A permanent's timestamp is set when it enters the battlefield (CR 613.7d, stamped by
 * [com.wingedsheep.engine.handlers.effects.PermanentEntryTracker.record]) and renewed when an
 * Aura or Equipment becomes attached (CR 613.7e), when the permanent turns face up or face down
 * (CR 613.7f), and when it transforms (CR 613.7g). The global timestamp ticks after each stamp,
 * so a floating effect created later in the same resolution still sorts after it.
 */
object LayerTimestamps {
    fun renew(state: GameState, entityId: EntityId): GameState {
        if (state.getEntity(entityId) == null) return state
        return state.updateEntity(entityId) { it.with(TimestampComponent(state.timestamp)) }.tick()
    }
}
